import type { AuthAdapter, Session } from './types';

const MOCK_SESSION: Session = {
  token: 'mock-token',
  refreshToken: 'mock-refresh-token',
  user: { id: 'mock-user', name: 'Mock User' },
};

/**
 * The default adapter. Inert — it talks to nothing, and exists so the app runs
 * and the auth flow is demonstrable before a backend exists.
 *
 * Replace it with `configureAuth(myAdapter)`; do not edit this file. That is the
 * whole point of the seam: you swap an implementation, you do not delete
 * scaffolding.
 */
export const mockAuthAdapter: AuthAdapter = {
  async signIn({ email, password }) {
    if (email === '' || password === '') {
      throw new Error('Email and password are required');
    }
    return MOCK_SESSION;
  },

  async signOut() {
    // no-op
  },

  async refresh() {
    return MOCK_SESSION;
  },
};
